mapper.select:
SELECT summary_id, user_id, `year_month`, summary_text, created_at
FROM report_ai_summary
WHERE user_id = #{userId}
  AND `year_month` = #{yearMonth}

mapper.delete:
DELETE FROM report_ai_summary
WHERE user_id = #{userId}
  AND `year_month` = #{yearMonth}

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM report_ai_summary
    WHERE user_id = #{userId}
      AND `year_month` = #{yearMonth}
      AND created_at > (NOW() - INTERVAL 10 MINUTE)
)
